"use strict";
// What schema libraries do with an enum object: take the values of its
// non-numeric own names, once each.
exports.Enum = (item) => {
  if (item === undefined || item === null) throw new Error("Enum undefined or empty");
  const values = Object.getOwnPropertyNames(item)
    .filter((key) => isNaN(key))
    .map((key) => item[key]);
  return { kind: "enum", anyOf: [...new Set(values)] };
};
exports.describe = (schema) => `${schema.kind}(${schema.anyOf.map((v) => JSON.stringify(v)).join("|")})`;
exports.check = (schema, value) => schema.anyOf.includes(value);
